  { q: "De quelle épopée parle Le Maître de la Parole ?", options: ["Samory Touré", "Soundiata Keïta", "Mansa Bakary"], answer: 1, fact: "Soundiata Keïta est le fondateur de l'empire du Mali. Le même empire que celui de Mansa Bakary dans L'Empereur de PATI." },
  { q: "Quel était le premier poste diplomatique de Camara Laye ?", options: ["Ambassadeur en France", "Ambassadeur au Ghana", "Ambassadeur en Côte d'Ivoire"], answer: 1, fact: "En 1958, à l'indépendance de la Guinée, Camara Laye devient le premier ambassadeur au Ghana." },
  { q: "Qu'est-ce qu'une veillée ?", options: ["Une cérémonie", "Un repas", "Réunion du soir où les anciens racontent des histoires"], answer: 2, fact: "La veillée est l'une des formes les plus importantes de transmission du savoir en Afrique de l'Ouest." },
  { q: "Quelle est la capitale de la Haute-Guinée ?", options: ["Kindia", "Faranah", "Kankan"], answer: 2, fact: "Kankan est la capitale de la Haute-Guinée, région malinké où se trouve Kouroussa." },
  { q: "Camara Laye était de quel peuple ?", options: ["Soussou", "Malinké", "Peul"], answer: 1, fact: "Camara Laye était Malinké de Haute-Guinée. Les Malinkés descendent de l'empire du Mali." },
  { q: "Pourquoi Camara Laye a-t-il écrit L'Enfant Noir ?", options: ["Pour devenir célèbre", "Pour gagner de l'argent", "Pour ne pas oublier son pays natal"], answer: 2 },
  { q: "Comment s'appelle la ville où vit Koumba ?", options: ["Conakry", "Siguiri", "Bamako"], answer: 1, fact: "Koumba Keita vit à Siguiri, en Haute-Guinée, la ville de l'or et la terre des ancêtres Keita." },
  { q: "Quel est le titre officiel de Ntoma ?", options: ["Professeure Koumba", "Docteure Koumba Fofana", "Hadja Koumba"], answer: 1, fact: "Docteure Koumba Fofana est chercheuse en plantes médicinales et voyage de Conakry à Bamako pour ses recherches." },
  { q: "Comment s'appelait l'empire qui régnait sur la Haute-Guinée au XIVe siècle ?", options: ["L'empire du Ghana", "L'empire songhay", "L'empire du Mali"], answer: 2, fact: "L'empire du Mali s'étendait des côtes de l'Atlantique jusqu'au lac Tchad — plus grand que toute l'Europe occidentale." },
  { q: "Quel événement Ntoma vient-elle célébrer à Siguiri ?", options: ["L'anniversaire de Koumba", "La mention au concours d'entrée en 6e", "La fin des vacances"], answer: 1, fact: "Koumba a réussi son concours d'entrée en 6e avec mention. C'est pour cela que Ntoma a fait 800 kilomètres." },
  { q: "Qui a raconté l'histoire d'Abu Bakr II au chroniqueur al-Umari ?", options: ["Le griot Narenaa", "Le capitaine Diaby", "Mansa Musa"], answer: 2, fact: "C'est Mansa Musa, cousin et successeur d'Abu Bakr II, qui a transmis le récit au chroniqueur al-Umari lors de son pèlerinage à La Mecque en 1324." },
  { q: "Combien de pirogues Abu Bakr II a-t-il envoyées lors de la première expédition ?", options: ["200", "2 000", "20 000"], answer: 0, fact: "La première expédition comptait 200 pirogues. Seule une pirogue revint, avec le capitaine Diaby comme seul survivant." },
  { q: "Que décrit le capitaine survivant au milieu de l'océan ?", options: ["Une île immense", "Un fleuve qui coule dans la mer", "Une tempête sans fin"], answer: 1, fact: "Le capitaine Diaby parle d'un courant immense — le fleuve dans l'océan — qui a emporté les pirogues. C'était probablement le courant nord-équatorial atlantique." },
  { q: "Qu'est-ce qu'un griot en Afrique de l'Ouest ?", options: ["Un chef de guerre", "Un marchand d'or", "Un gardien de la mémoire"], answer: 2, fact: "Le griot (jeli en malinké) est historien, musicien, poète et conseiller. Il transmet de génération en génération les histoires des familles et des royaumes." },
  { q: "Que fait Koumba à la fin du livre ?", options: ["Elle écrit une lettre à Ntoma", "Elle raconte l'histoire à sa classe", "Elle part au Mali"], answer: 1, fact: "Koumba écrit au tableau : « Et si deux humanités s'étaient tendu la main ? » et son maître décide de chercher la réponse avec toute la classe." },
  { q: "Quelle phrase Koumba écrit-elle au tableau ?", options: ["Christophe Colomb n'a pas découvert l'Amérique", "Et si deux humanités s'étaient tendu la main ?", "L'Afrique était la plus grande puissance du monde"], answer: 1, fact: "Cette phrase est l'écho de la prophétie du griot Narenaa, qui voyage à travers les siècles de génération en génération." },
  { q: "Quel était le rêve d'Abu Bakr II ?", options: ["Conquérir de nouvelles terres", "Voir ce qui se trouvait de l'autre côté de l'océan", "Devenir le plus riche des empereurs"], answer: 1, fact: "Abu Bakr II était fasciné par l'océan Atlantique. Il rêvait de savoir ce qui se trouvait au-delà de l'horizon." },
  { q: "Qui est Narenaa ?", options: ["Le conseiller d'Abu Bakr II", "Le griot du palais de Niani", "Le capitaine de la première expédition"], answer: 1, fact: "Narenaa est le vieux griot du palais de Niani. Sa kora chante la prophétie du voyage. C'est le personnage le plus mystique du récit." },
  { q: "Que s'est-il passé après la première expédition ?", options: ["Abu Bakr II a abandonné son projet", "Il a abdiqué et parti avec 2 000 pirogues", "Il a envoyé Mansa Musa à sa place"], answer: 1, fact: "Après le retour du seul survivant, Abu Bakr II a compris que la traversée était possible. Il a abdiqué en faveur de Mansa Musa et est parti avec 2 000 pirogues." },
  { q: "Pourquoi Abu Bakr II est-il important aujourd'hui ?", options: ["Il a découvert l'Amérique avant Colomb", "Son histoire pose la question des contributions africaines à l'histoire mondiale", "Il a fondé l'empire du Mali"], answer: 1, fact: "L'histoire d'Abu Bakr II interroge ce qu'on apprend à l'école et rappelle que l'Afrique a une histoire maritime riche et méconnue." },
  { q: "Quel est le lien entre Ntoma et Koumba ?", options: ["Elles sont mère et fille", "Elles sont homonymes (Ntoma)", "Elles sont voisines"], answer: 1, fact: "En Guinée, l'homonyme (ntoma en malinké) est la personne qui vous a donné son prénom. Ce lien dépasse la parenté de sang — c'est une transmission spirituelle." },
  { q: "Comment s'appelle l'héroïne du livre ?", options: ["Mariama", "Yarie", "Fifi"], answer: 1, fact: "Yarie est une fille de 11 ans qui vit à Conakry. Son père travaille pour une compagnie minière." },
  { q: "Dans quelle préfecture habite Mamie Fanta ?", options: ["Conakry", "Kindia", "Boffa"], answer: 2, fact: "Mamie Fanta habite à Tamita, dans la préfecture de Boffa, au cœur des mines de bauxite." },
  { q: "La Guinée possède quel % des réserves mondiales de bauxite ?", options: ["5%", "25-33%", "70%"], answer: 1, fact: "La Guinée détient entre un quart et un tiers des réserves mondiales de bauxite — les plus importantes au monde." },
  { q: "De quoi est principalement composée la bauxite ?", options: ["Sable et argile", "Fer et aluminium", "Charbon et soufre"], answer: 1, fact: "La bauxite est une roche sédimentaire rouge composée de fer et d'aluminium, formée il y a des millions d'années." },
  { q: "Que produit-on à partir de la bauxite ?", options: ["Du fer", "Du pétrole", "De l'aluminium"], answer: 2, fact: "De la bauxite, on tire l'alumine. De l'alumine, on fabrique l'aluminium." },
  { q: "Quel est le principal impact environnemental des mines à ciel ouvert ?", options: ["Pollution air et eau, dégradation terres", "Réchauffement climatique seul", "Aucun impact"], answer: 0, fact: "80% des exploitations minières guinéennes sont à ciel ouvert." },
  { q: "Quel métier veut exercer Tchotcho ?", options: ["Géologue", "Agronome", "Avocat"], answer: 1, fact: "Tchotcho veut devenir agronome — un spécialiste qui sait comment faire produire la terre durablement." },
  { q: "Qu'est-ce qu'une semence traditionnelle ?", options: ["Une graine importée", "Graine transmise de génération en génération", "Graine modifiée"], answer: 1, fact: "Les semences traditionnelles sont adaptées aux sols locaux et transmises de mère en fille." },
  { q: "L'aluminium vaut combien de fois plus que la bauxite brute ?", options: ["5 fois", "60 fois", "100 fois"], answer: 1, fact: "1 kg de bauxite brute = 0,04$. 1 kg d'aluminium = 2,50$. Soit 60 fois plus." },
  { q: "Qu'est-ce que la souveraineté alimentaire ?", options: ["Manger du riz tous les jours", "Droit d'un peuple à définir sa politique alimentaire", "Exporter sa nourriture"], answer: 1, fact: "Un pays qui ne cultive pas sa terre dépend des autres pour manger." },
  { q: "En Guinée, qui assure plus de 60% de la production agricole ?", options: ["Les hommes", "Les enfants", "Les femmes"], answer: 2, fact: "Les femmes guinéennes assurent plus de 60% de la production agricole alimentaire." },
  { q: "Où se trouvent les principaux gisements de bauxite guinéens ?", options: ["Haute-Guinée", "Guinée forestière", "Basse-Guinée"], answer: 2, fact: "Les plus grands gisements de bauxite se trouvent en Basse-Guinée : Boké, Boffa et Kindia." },
  { q: "Que signifie 'mine à ciel ouvert' ?", options: ["Mine sous la mer", "Mine creusée en surface", "Mine abandonnée"], answer: 1, fact: "80% des exploitations minières guinéennes sont à ciel ouvert." },
  { q: "Que représente le sachet de graines que Mamie donne à Yarie ?", options: ["Un cadeau commercial", "La transmission d'un héritage agricole", "Une recette de cuisine"], answer: 1, fact: "« Des graines de chez nous. Pas des graines importées. Les nôtres. Celles que ma mère m'a données, et sa mère avant elle. »" },
  { q: "Comment s'appelle l'héroïne de Sauver le Milo ?", options: ["Kadiatou Kaba", "Aminata Diakité", "Kankou Cissé"], answer: 0, fact: "Kadiatou Kaba a 13 ans. À 10 ans, elle a soufflé à son frère l'idée de sauver le Milo." },
  { q: "Quel âge a Sory, le grand frère ?", options: ["18 ans", "22 ans", "30 ans"], answer: 1, fact: "Sory a 22 ans. Il est étudiant à Conakry et délégué de son Sèdè." },
  { q: "Où habite Bâba Karamoko Kaba ?", options: ["Conakry", "Kankan, Banankoroda", "Abidjan"], answer: 1, fact: "Bâba Karamoko vit à Kankan, quartier Banankoroda. Ancien Sömönö champion en 1972." },
  { q: "Quel est le métier de Jeli Kouyaté ?", options: ["Enseignant", "Agent de police / Jeli", "Médecin"], answer: 1, fact: "Jeli Kouyaté est policier le jour, jeli aux grandes occasions. « Ça s'appelle être deux choses à la fois. »" },
  { q: "Qu'est-ce que la Mamaya ?", options: ["Un fleuve", "Un festival de Kankan tous les 7 ans", "Une danse"], answer: 1, fact: "La Mamaya est le plus grand festival d'Afrique de l'Ouest. Elle a lieu tous les 7 ans à Kankan." },
  { q: "Qu'est-ce qu'un Sèdè ?", options: ["Une pirogue", "Une cohorte de jeunes pour la Mamaya", "Un griot"], answer: 1, fact: "Le Sèdè est une cohorte de jeunes (20-30 ans) à qui est assignée une année de Mamaya tous les 7 ans." },
  { q: "Qu'est-ce qu'un Sömönö ?", options: ["Champion de course de pirogue", "Musicien", "Maire"], answer: 0, fact: "Les Sömönö sont les champions de course de pirogue sur le Milo. Bâba Karamoko était champion en 1972." },
  { q: "D'où vient Karifalla ?", options: ["Conakry", "Abidjan", "New York"], answer: 1, fact: "Karifalla vient d'Abidjan. Maninka-dyula, français mêlé de nouchi." },
  { q: "D'où vient Aminata ?", options: ["Conakry", "Paris", "New York"], answer: 2, fact: "Aminata Kaba Diakité vient de New York. Elle filme tout." },
  { q: "Quelle est la phrase centrale du livre ?", options: ["« Le Milo est à nous »", "« Tout le monde a sa place pour bien faire »", "« Sauvons le fleuve »"], answer: 1, fact: "« Tout le monde a sa place pour bien faire » est une maxime maninka. Les grands ramassent, les enfants parlent." },
  { q: "Que fait le cercle des cadets ?", options: ["Nettoie le fleuve", "Fait du porte-à-porte", "Construit le belvédère"], answer: 1, fact: "Les cadets (10-14 ans) font du porte-à-porte pour sensibiliser les gens." },
  { q: "Quel projet Sory présente ?", options: ["Un stade", "Un belvédère sur le Milo", "Un pont"], answer: 1, fact: "Sory lance un crowdfunding pour un belvédère au-dessus du Milo." },
  { q: "Que fait Bâba le jour de la parade ?", options: ["Reste assis", "Pose sa canne et rame", "Fait un discours"], answer: 1, fact: "Bâba pose sa canne « comme un drapeau » et monte dans une pirogue." },
  { q: "Quel est le lien avec l'UNESCO ?", options: ["Candidature Mamaya au patrimoine immatériel", "Livre traduit en 10 langues", "Kankan classée ville historique"], answer: 0, fact: "Le livre accompagne la candidature de la Mamaya au patrimoine culturel immatériel de l'UNESCO." },
  { q: "Quelle inscription Kadiatou ajoute-t-elle au dos de la photo ?", options: ["« Sauver le Milo »", "« Notre titre. »", "« Kankan 2026 »"], answer: 1, fact: "Sous l'inscription de 1972, Kadiatou écrit : « Milo, 2026. Notre titre. »" }
